        "madhab_shafi": [.indonesian: "Syafi'i", .english: "Shafi'i", .malay: "Syafi'i"],
        "manzil_benefits_list": [.indonesian: "Memungkinkan khataman Al-Quran secara rutin — satu kali per minggu.|Membangun hubungan yang kuat dan konsisten dengan Kitab Allah.|Membaca keseluruhan Al-Quran secara teratur mendatangkan pahala yang besar dan ampunan.|Mendorong tadabbur harian pada berbagai bagian Al-Quran.|Pendekatan terstruktur yang direkomendasikan oleh ulama klasik dan diwariskan turun-temurun.", .english: "Enables regular completion (khatam) of the Quran — once per week.|Builds a strong, consistent relationship with the Book of Allah.|Reciting the entire Quran regularly earns great reward and forgiveness.|Encourages daily reflection on different parts of the Quran.|A structured approach recommended by classical scholars and passed down through generations.", .malay: "Membolehkan khatam Al-Quran secara rutin — sekali seminggu.|Membina hubungan yang kukuh dan konsisten dengan Kitab Allah.|Membaca keseluruhan Al-Quran secara tetap mendatangkan pahala yang besar dan keampunan.|Menggalakkan tadabbur harian pada bahagian-bahagian Al-Quran yang berbeza.|Pendekatan berstruktur yang disyorkan oleh ulama klasik dan diwarisi turun-temurun."],
        "manzil_benefits_title": [.indonesian: "Keutamaan & Manfaat", .english: "Virtues & Benefits", .malay: "Kelebihan & Faedah"],
        "manzil_col_juz": [.indonesian: "Juz", .english: "Juz", .malay: "Juz"],
        "manzil_col_manzil": [.indonesian: "Manzil", .english: "Manzil", .malay: "Manzil"],
        "manzil_col_surah": [.indonesian: "Rentang Surah", .english: "Surah Range", .malay: "Julat Surah"],
        "manzil_desc_al_araf": [.indonesian: "Tuhanmu menciptakan langit dan bumi dalam enam masa — serulah Dia dengan rendah hati dan sembunyi.", .english: "Your Lord created the heavens and earth in six days — call upon Him humbly and in secret.", .malay: "Tuhanmu menciptakan langit dan bumi dalam enam masa — serulah Dia dengan rendah hati dan tersembunyi."],
        "manzil_desc_al_falaq": [.indonesian: "Berlindung kepada Tuhan Subuh dari kejahatan makhluk, malam gelap, sihir, dan iri hati.", .english: "Seek refuge with the Lord of daybreak from the evil of creation, darkness, sorcery, and envy.", .malay: "Berlindung kepada Tuhan Waktu Subuh daripada kejahatan makhluk, malam gelap, sihir, dan iri hati."],
        "manzil_desc_al_hasyr": [.indonesian: "Jika Quran ini diturunkan ke atas gunung, niscaya ia akan runtuh — Dialah Allah, Pencipta, Pembentuk Rupa, Nama-Nama Terindah.", .english: "If this Quran were sent upon a mountain, it would crumble — He is Allah, the Creator, the Bestower of Forms, the Most Beautiful Names.", .malay: "Jika Quran ini diturunkan ke atas gunung, nescaya ia akan runtuh — Dialah Allah, Pencipta, Pembentuk Rupa, Nama-Nama Terindah."],
        "manzil_desc_al_ikhlas": [.indonesian: "Intisari Tauhid — Dialah Allah, Maha Esa, Tempat Bergantung, tidak beranak dan tidak dilahirkan.", .english: "The essence of Tawheed — He is Allah, the One, the Eternal Refuge, who begets not nor is begotten.", .malay: "Intisari Tauhid — Dialah Allah, Maha Esa, Tempat Bergantung, tidak beranak dan tidak diperanakkan."],
        "manzil_desc_al_isra": [.indonesian: "Serulah Allah atau Ar-Rahman — milik-Nya Nama-Nama Terindah. Segala puji bagi-Nya yang tidak beranak dan tidak bersekutu.", .english: "Call upon Allah or Ar-Rahman — to Him belong the Most Beautiful Names. Praise be to Him who has no son nor partner.", .malay: "Serulah Allah atau Ar-Rahman — milik-Nya Nama-Nama Terindah. Segala puji bagi-Nya yang tidak beranak dan tidak bersekutu."],
        "manzil_desc_al_jinn": [.indonesian: "Serombongan jin mendengar Quran, beriman, dan menyatakan iman mereka — Tuhan kami tidak beristri dan tidak beranak.", .english: "A group of jinn heard the Quran, believed, and declared their faith — our Lord has no spouse or child.", .malay: "Sekumpulan jin mendengar Quran, beriman, dan menyatakan iman mereka — Tuhan kami tidak beristeri dan tidak beranak."],
        "manzil_desc_al_kafirun": [.indonesian: "Pernyataan pemutusan dari kekafiran — bagimu agamamu, bagiku agamaku.", .english: "A declaration of disavowal from disbelief — to you your religion, to me mine.", .malay: "Pernyataan pemutusan daripada kekufuran — bagimu agamamu, bagiku agamaku."],
        "manzil_desc_al_muminun": [.indonesian: "Apakah kamu diciptakan tanpa tujuan? Maha Tinggi Allah, Raja Sejati — mohon ampunan dan rahmat-Nya.", .english: "Were you created without purpose? Exalted is Allah, the True King — seek His forgiveness and mercy.", .malay: "Adakah kamu diciptakan tanpa tujuan? Maha Tinggi Allah, Raja Sejati — mohon keampunan dan rahmat-Nya."],
        "manzil_desc_ali_imran_18": [.indonesian: "Allah bersaksi tiada tuhan selain Dia — Yang Maha Perkasa, Maha Bijaksana.", .english: "Allah testifies that there is no deity but Him — the Almighty, the All-Wise.", .malay: "Allah bersaksi tiada tuhan selain Dia — Yang Maha Perkasa, Maha Bijaksana."],
        "manzil_desc_ali_imran_26": [.indonesian: "Katakanlah: Wahai Allah, Pemilik kerajaan — Engkau memberi kemuliaan kepada siapa yang Engkau kehendaki.", .english: "Say: O Allah, Owner of sovereignty — You give honour and power to whom You will.", .malay: "Katakanlah: Wahai Allah, Pemilik kerajaan — Engkau memuliakan sesiapa yang Engkau kehendaki."],
        "manzil_desc_ali_imran_27": [.indonesian: "Engkau masukkan malam ke siang dan hidup dari yang mati — Engkau memberi rezeki tanpa hisab.", .english: "You cause the night to enter the day and bring the living from the dead — You provide for whom You will without measure.", .malay: "Engkau masukkan malam ke siang dan hidup daripada yang mati — Engkau memberi rezeki tanpa hisab."],
        "manzil_desc_an_nas": [.indonesian: "Berlindung kepada Tuhan manusia, Raja manusia, dari bisikan setan yang bersembunyi.", .english: "Seek refuge with the Lord of mankind, the King of mankind, from the whisperer who withdraws.", .malay: "Berlindung kepada Tuhan manusia, Raja manusia, daripada bisikan syaitan yang bersembunyi."],
        "manzil_desc_ar_rahman": [.indonesian: "Wahai jin dan manusia — tiada yang lolos dari kekuasaan Allah. Maka nikmat Tuhanmu yang manakah yang kamu dustakan?", .english: "O assembly of jinn and men — none can escape Allah's authority. Which of your Lord's favours will you deny?", .malay: "Wahai jin dan manusia — tiada yang boleh lolos daripada kekuasaan Allah. Maka nikmat Tuhanmu yang manakah yang kamu dustakan?"],
        "manzil_desc_ash_shaffat": [.indonesian: "Demi malaikat yang berbaris dalam saf — Tuhanmu Maha Esa, Rabb langit dan bumi.", .english: "By the angels ranged in rows — your God is One, Lord of the heavens and the earth.", .malay: "Demi malaikat yang berbaris dalam saf — Tuhanmu Maha Esa, Rabb langit dan bumi."],
        "manzil_desc_ayat_kursi": [.indonesian: "Ayat teragung dalam Al-Quran — benteng perlindungan. Siapa membacanya di malam hari akan tetap dalam perlindungan Allah hingga pagi.", .english: "The greatest verse in the Quran — a fortress of protection. Whoever recites it at night remains under Allah's protection until morning.", .malay: "Ayat teragung dalam Al-Quran — benteng perlindungan. Sesiapa membacanya pada waktu malam akan kekal dalam perlindungan Allah hingga pagi."],
        "manzil_desc_baqarah_1": [.indonesian: "Lanjutkan dengan awal Al-Baqarah — petunjuk bagi yang bertakwa dan jalan menuju kesuksesan.", .english: "Continue with the opening of Al-Baqarah — guidance for the God-conscious and the path to success.", .malay: "Sambung dengan awal Al-Baqarah — petunjuk bagi yang bertakwa dan jalan menuju kejayaan."],
        "manzil_desc_baqarah_163": [.indonesian: "Tuhanmu Maha Esa — tiada tuhan selain Dia, Maha Pengasih, Maha Penyayang.", .english: "Your God is One — there is no deity but Him, the Most Gracious, the Most Merciful.", .malay: "Tuhanmu Maha Esa — tiada tuhan selain Dia, Maha Pengasih, Maha Penyayang."],
        "manzil_desc_baqarah_256": [.indonesian: "Tidak ada paksaan dalam agama — kebenaran telah nyata dari kesesatan.", .english: "There is no compulsion in religion — truth has become clear from falsehood.", .malay: "Tiada paksaan dalam agama — kebenaran telah nyata daripada kesesatan."],
        "manzil_desc_baqarah_257": [.indonesian: "Allah Pelindung orang-orang beriman, mengeluarkan mereka dari kegelapan kepada cahaya.", .english: "Allah is the Protector of the believers, bringing them from darkness into light.", .malay: "Allah Pelindung orang-orang beriman, mengeluarkan mereka daripada kegelapan kepada cahaya."],
        "manzil_desc_baqarah_284": [.indonesian: "Milik Allah apa yang di langit dan bumi — Dia akan memperhitungkan apa yang ada di hatimu.", .english: "To Allah belongs all that is in the heavens and earth — He will call you to account for what is in your hearts.", .malay: "Milik Allah apa yang di langit dan bumi — Dia akan memperhitungkan apa yang ada di hati kamu."],
        "manzil_desc_baqarah_285": [.indonesian: "Rasul dan orang beriman beriman pada wahyu — kami dengar dan kami taat, mohon ampunan-Mu.", .english: "The Messenger and believers have faith in what was revealed — we hear and we obey, seeking Your forgiveness.", .malay: "Rasul dan orang beriman beriman pada wahyu — kami dengar dan kami taat, mohon keampunan-Mu."],
        "manzil_desc_baqarah_286": [.indonesian: "Allah tidak membebani jiwa melampaui kemampuannya — doa penutup Al-Baqarah memohon ampunan dan pertolongan.", .english: "Allah does not burden a soul beyond its capacity — the closing supplication of Al-Baqarah for forgiveness and help.", .malay: "Allah tidak membebankan jiwa melampaui kemampuannya — doa penutup Al-Baqarah memohon keampunan dan pertolongan."],
        "manzil_desc_fatihah": [.indonesian: "Bacaan Manzil dimulai dengan Al-Fatihah — surah teragung, dibaca di setiap rakaat sholat. Penyembuh dan pelindung.", .english: "Begin Manzil with Al-Fatihah — the greatest surah, recited in every rakah. A cure and protection.", .malay: "Bacaan Manzil dimulakan dengan Al-Fatihah — surah teragung, dibaca dalam setiap rakaat solat. Penawar dan pelindung."],
        "manzil_fami_desc": [.indonesian: "Ungkapan kunci yang berarti \"mulutku selalu rindu (membaca Al-Quran)\". Tujuh huruf — ف م ي ب ش و ق — adalah huruf awal dari surah yang memulai setiap Manzil: Al-Fatihah, Al-Ma'idah, Yunus, Al-Isra', Asy-Syu'ara, Ash-Shaffat, dan Qaf.", .english: "A mnemonic phrase meaning \"My mouth longs to recite (the Quran)\". The 7 letters — ف م ي ب ش و ق — are the first letters of the surah that begins each of the 7 Manzils: Al-Fatihah, Al-Ma'idah, Yunus, Al-Isra', Ash-Shu'ara, Ash-Shaffat, and Qaf.", .malay: "Ungkapan mnemonik bermaksud \"mulutku sentiasa rindu (membaca Al-Quran)\". Tujuh huruf — ف م ي ب ش و ق — ialah huruf pertama bagi surah yang memulakan setiap Manzil: Al-Fatihah, Al-Ma'idah, Yunus, Al-Isra', Asy-Syu'ara, Ash-Shaffat, dan Qaf."],
        "manzil_fami_label": [.indonesian: "Fami bi Syauqin (فَمِي بِشَوْقٍ)", .english: "Fami bi Shawqin (فَمِي بِشَوْقٍ)", .malay: "Fami bi Syauqin (فَمِي بِشَوْقٍ)"],
        "manzil_header_body": [.indonesian: "Kumpulan ayat pilihan untuk perlindungan dari sihir, jin, dan gangguan, disusun oleh ulama di anak benua India.", .english: "A collection of selected verses for protection from sihr, jinn, and harm, compiled by scholars in the Indian subcontinent.", .malay: "Kumpulan ayat pilihan untuk perlindungan dari sihir, jin, dan gangguan, disusun oleh ulama di anak benua India."],
        "manzil_header_title": [.indonesian: "Perlindungan dari Al-Quran", .english: "Protection from the Quran", .malay: "Perlindungan dari Al-Quran"],
        "manzil_how_body": [.indonesian: "Setiap hari, bacalah satu Manzil secara berurutan dari Senin hingga Minggu, sehingga khatam Al-Quran dalam satu minggu. Boleh dibaca dalam satu dudukan atau dibagi dalam beberapa sesi sepanjang hari (misalnya setelah Subuh, Zuhur, Asar, Maghrib, dan Isya').\\n\\nUntuk memulai, bacalah Manzil 1 (Juz 1–6) dan lanjutkan ke Manzil berikutnya setiap hari. Istiqamah adalah kuncinya — meskipun tidak bisa menyelesaikan satu Manzil penuh dalam sehari, usahakan minimal membaca sebagian dan lanjutkan keesokan harinya.", .english: "Each day, recite one Manzil in sequence from Monday to Sunday, completing the entire Quran in one week. You may recite it in one sitting or spread it across multiple sessions during the day (e.g. after Fajr, Zuhr, Asr, Maghrib, and Isya').\\n\\nTo begin, start with Manzil 1 (Juz 1–6) and proceed to the next Manzil each day. Consistency is key — even if you cannot complete a full Manzil in a day, try to at least read a portion and continue the next day.", .malay: "Setiap hari, bacalah satu Manzil secara berurutan dari Isnin hingga Ahad, bagi menamatkan seluruh Al-Quran dalam masa seminggu. Boleh dibaca dalam satu duduk atau dibahagikan kepada beberapa sesi sepanjang hari (contohnya selepas Subuh, Zohor, Asar, Maghrib, dan Isyak).\\n\\nUntuk bermula, mulakan dengan Manzil 1 (Juz 1–6) dan teruskan ke Manzil berikutnya setiap hari. Istiqamah adalah kunci — walaupun tidak dapat menyelesaikan satu Manzil penuh dalam sehari, usahakan sekurang-kurangnya membaca sebahagian dan teruskan keesokan harinya."],
        "manzil_how_title": [.indonesian: "Cara Mengamalkan", .english: "How to Practice", .malay: "Cara Mengamalkan"],
        "manzil_info_definition": [.indonesian: "Manzil (bahasa Arab: منزل) adalah sistem pembagian pembacaan Al-Quran untuk memudahkan penyelesaian (khataman) Al-Quran selama tujuh hari (seminggu). Tradisi ini umum dipraktikkan di komunitas Muslim Asia Selatan dan dipopulerkan oleh ulama seperti Syah Waliullah al-Dahlawi.\\n\\nCatatan: \"Manzil\" di sini merujuk pada pembagian 7 bagian Al-Quran untuk khataman, berbeda dari ayat-ayat ruqyah perlindungan (Manzil ruqyah) yang dikumpulkan oleh Maulana Zakariyya Kandhlawi. Bagian ini dalam aplikasi membahas ayat-ayat perlindungan.", .english: "Manzil (Arabic: منزل) is a system for dividing the recitation of the Quran to facilitate completing (khatam) the Quran over seven days (one week). This tradition is widely practiced in South Asian Muslim communities and has been popularized by scholars such as Shah Waliullah al-Dehlawi.\\n\\nNote: \"Manzil\" here refers to the 7-part Quran division for khatam, and is different from the protection verses (Manzil ruqyah) compiled by Maulana Zakariyya Kandhlawi. This section in the app covers the protection verses.", .malay: "Manzil (bahasa Arab: منزل) ialah sistem pembahagian bacaan Al-Quran bagi memudahkan penyelesaian (khatam) Al-Quran dalam tempoh tujuh hari (seminggu). Tradisi ini lazim diamalkan dalam komuniti Muslim Asia Selatan dan dipopularkan oleh ulama seperti Syah Waliullah al-Dahlawi.\\n\\nNota: \"Manzil\" di sini merujuk kepada pembahagian 7 bahagian Al-Quran untuk khatam, dan adalah berbeza daripada ayat-ayat ruqyah perlindungan (Manzil ruqyah) yang dikumpulkan oleh Maulana Zakariyya Kandhlawi. Bahagian ini dalam aplikasi merangkumi ayat-ayat perlindungan."],
        "manzil_info_subtitle": [.indonesian: "Definisi, pembagian 7 hari & panduan amalan", .english: "Definition, 7-day division & practice guide", .malay: "Definisi, pembahagian 7 hari & panduan amalan"],
