        "share_reminder_afternoon_1": [.indonesian: "berhenti sejenak di tengah hari dan luruskan kembali hatimu pada kebenaran.", .english: "pause in the middle of your day and realign your heart with what is true.", .malay: "berhenti sejenak di tengah hari dan luruskan semula hati pada kebenaran."],
        "share_reminder_afternoon_2": [.indonesian: "jaga kedamaianmu dengan menyaring apa yang kamu dengar dan ulang.", .english: "protect your peace by filtering what you hear and what you repeat.", .malay: "jaga ketenangan dengan menapis apa yang anda dengar dan ulang."],
        "share_reminder_afternoon_3": [.indonesian: "biarkan ayat ini menghentikan asumsi dan mengembalikan kejernihan.", .english: "let this verse interrupt assumptions and restore clarity.", .malay: "biarkan ayat ini hentikan andaian dan pulihkan kejelasan."],
        "share_reminder_evening_1": [.indonesian: "sebelum hari berakhir, kembalikan hatimu pada kebenaran dan kerendahan hati.", .english: "before the day closes, return your heart to truth and humility.", .malay: "sebelum hari berakhir, kembalikan hati pada kebenaran dan kerendahan diri."],
        "share_reminder_evening_2": [.indonesian: "perlambat langkah malam ini dan lepaskan kesimpulan yang dibentuk tanpa kepastian.", .english: "slow down tonight and release conclusions you built without certainty.", .malay: "perlahankan langkah malam ini dan lepaskan kesimpulan tanpa kepastian."],
        "share_reminder_evening_3": [.indonesian: "biarkan ayat ini membersihkan kebisingan hari ini sebelum masuk ke hatimu.", .english: "let this verse cleanse today's noise before it enters your heart.", .malay: "biarkan ayat ini bersihkan kebisingan hari sebelum masuk ke hati."],
        "share_reminder_morning_1": [.indonesian: "mulailah hari dengan kejernihan sebelum kamu menyerap setiap suara di sekitarmu.", .english: "start your day with clarity before you absorb every voice around you.", .malay: "mulakan hari dengan kejelasan sebelum anda menyerap setiap suara di sekeliling."],
        "share_reminder_morning_2": [.indonesian: "tanamkan niat sejak pagi: verifikasi sebelum percaya, dan renungkan sebelum bereaksi.", .english: "set your intention early: verify before believing, and reflect before reacting.", .malay: "tanam niat awal: sahkan sebelum percaya, dan renung sebelum bertindak balas."],
        "share_reminder_morning_3": [.indonesian: "jadikan ayat ini jangkar pikiranmu sebelum kesibukan datang.", .english: "let this verse anchor your mind before the rush begins.", .malay: "jadikan ayat ini sauh minda sebelum kesibukan bermula."],
        "share_reminder_night_1": [.indonesian: "sebelum tidur, tinggalkan gosip dan pegang teguh apa yang jelas.", .english: "before you rest, leave rumours behind and hold on to what is clear.", .malay: "sebelum tidur, tinggalkan khabar angin dan pegang apa yang jelas."],
        "share_reminder_night_2": [.indonesian: "akhiri malam dengan renungan, bukan asumsi.", .english: "close your night with reflection, not assumptions.", .malay: "akhiri malam dengan renungan, bukan andaian."],
        "share_reminder_night_3": [.indonesian: "jadikan ayat ini filter terakhir sebelum kamu beristirahat.", .english: "let this verse be your final filter before sleep.", .malay: "jadikan ayat ini penapis terakhir sebelum rehat."],
